CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(100) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,phone VARCHAR(25),role VARCHAR(20) NOT NULL DEFAULT 'customer' CHECK(role IN('customer','professional','admin')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS provider_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,business_name VARCHAR(120) NOT NULL,bio TEXT,location VARCHAR(180),verified BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),provider_id UUID NOT NULL REFERENCES provider_profiles(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL,description TEXT,price_kes NUMERIC(12,2) NOT NULL CHECK(price_kes>0),duration_minutes INTEGER NOT NULL CHECK(duration_minutes>0),active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),customer_id UUID NOT NULL REFERENCES users(id),provider_id UUID NOT NULL REFERENCES provider_profiles(id),service_id UUID NOT NULL REFERENCES services(id),scheduled_at TIMESTAMPTZ NOT NULL,amount_kes NUMERIC(12,2) NOT NULL,notes TEXT,status VARCHAR(20) DEFAULT 'pending' CHECK(status IN('pending','confirmed','completed','cancelled')),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID NOT NULL REFERENCES bookings(id),customer_id UUID NOT NULL REFERENCES users(id),provider_id UUID NOT NULL REFERENCES provider_profiles(id),amount_kes NUMERIC(12,2) NOT NULL,commission_kes NUMERIC(12,2) NOT NULL,professional_amount_kes NUMERIC(12,2) NOT NULL,provider_reference TEXT UNIQUE,status VARCHAR(20) DEFAULT 'pending' CHECK(status IN('pending','paid','failed','refunded')),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id),customer_id UUID NOT NULL REFERENCES users(id),provider_id UUID NOT NULL REFERENCES provider_profiles(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS messages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_services_category ON services(category);
CREATE INDEX IF NOT EXISTS idx_bookings_customer ON bookings(customer_id);
CREATE INDEX IF NOT EXISTS idx_bookings_provider ON bookings(provider_id);
